const openai = {
    name: 'openai',
    apiBase: 'https://api.openai.com/v1',
    model: 'text-embedding-3-small',
    dimensions: 1536,
    headers: (key) => ({
        Authorization: `Bearer ${key}`,
        'Content-Type': 'application/json',
    }),
};
const vercel = {
    name: 'vercel',
    apiBase: 'https://ai-gateway.vercel.sh/v1',
    model: 'openai/text-embedding-3-small',
    dimensions: 1536,
    headers: (key) => ({
        Authorization: `Bearer ${key}`,
        'Content-Type': 'application/json',
    }),
};
export function detectProvider(key) {
    if (key.startsWith('REPLAY_LAT_LLM_KEY::')) {
        const replayUrl = key.slice('REPLAY_LAT_LLM_KEY::'.length);
        return {
            name: 'replay',
            apiBase: replayUrl,
            model: 'replay',
            dimensions: 1536,
            headers: () => ({ 'Content-Type': 'application/json' }),
        };
    }
    if (key.startsWith('sk-ant-')) {
        throw new Error("Anthropic doesn't offer an embedding model. Set LAT_LLM_KEY to an OpenAI (sk-...) or Vercel AI Gateway (vck_...) key.");
    }
    if (key.startsWith('vck_'))
        return applyEnvOverrides(vercel, key);
    if (key.startsWith('sk-'))
        return applyEnvOverrides(openai, key);
    // ollama / local OpenAI-compatible: LAT_LLM_KEY=ollama (no auth required)
    if (key === 'ollama' || key === 'local') {
        const baseUrl = process.env.LAT_LLM_BASE_URL || 'http://localhost:11434/v1';
        const model = process.env.LAT_LLM_MODEL || 'nomic-embed-text';
        return {
            name: 'ollama',
            apiBase: baseUrl,
            model,
            dimensions: 768,
            headers: () => ({ 'Content-Type': 'application/json' }),
        };
    }
    // Custom OpenAI-compatible provider: any key when LAT_LLM_BASE_URL is set
    const baseUrl = process.env.LAT_LLM_BASE_URL;
    if (baseUrl) {
        const model = process.env.LAT_LLM_MODEL || 'text-embedding-3-small';
        const dimensions = parseInt(process.env.LAT_LLM_DIMENSIONS || '1536', 10);
        return {
            name: 'custom',
            apiBase: baseUrl,
            model,
            dimensions,
            headers: (k) => ({
                Authorization: `Bearer ${k}`,
                'Content-Type': 'application/json',
            }),
        };
    }
    throw new Error(`Unrecognized LAT_LLM_KEY prefix. Supported: OpenAI (sk-...), Vercel AI Gateway (vck_...), Ollama (ollama), or set LAT_LLM_BASE_URL for custom providers.`);
}
function applyEnvOverrides(provider, key) {
    const baseUrl = process.env.LAT_LLM_BASE_URL;
    const model = process.env.LAT_LLM_MODEL;
    if (!baseUrl && !model) return provider;
    return {
        ...provider,
        ...(baseUrl ? { apiBase: baseUrl } : {}),
        ...(model ? { model } : {}),
    };
}
